use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        // The result vector has exactly the same length as the input
        result.len() == a.len(),
        // And every entry of the result is 1
        result@ == seq![1; a.len() as nat],
{
    let n = a.len();
    // Pre-allocate the vector with capacity n
    let mut result: Vec<i32> = Vec::with_capacity(n);

    let mut i = 0;
    while i < n
        invariant
            // we never exceed n iterations
            i <= n,
            // the length of result so far equals the loop counter
            result.len() == i,
            // and the contents are all 1's
            result@ == seq![1; (i as nat)],
        decreases (n - i) as nat,
    {
        result.push(1);
        i += 1;
    }

    result
}

} // end of verus! block

